package glitch

import data.glitch_lib

# Set of keywords indicating public access or over-permission
public_access_keywords := {"public", "publicaccess", "ispublic", "publiclyaccessible", "acl", "grant", "allow", "anonymous", "everyone", "allusers", "authenticatedusers", "worldread", "worldwrite", "worldexecute", "0.0.0.0/0", "::/0"}

# Set of keywords indicating missing or weak authentication
auth_keywords := {"authentication", "auth", "mfa", "oidc", "saml", "password", "secret", "key", "root", "admin", "superuser", "enableclassic"}

# Set of keywords indicating excessive permissions (IAM)
iam_keywords := {"effect", "action", "resource", "administratoraccess", "fullaccess", "superuser", "assumerole", "privileged", "capability"}

# Set of keywords indicating network boundary issues
network_keywords := {"vpc", "subnet", "private", "public", "internetgateway", "egress", "ingress", "peer", "connect", "endpoint", "gateway", "route"}

# Set of keywords indicating file permission issues
file_keywords := {"mode", "permissions", "chmod", "owner", "group", "other", "read", "write", "execute", "worldwritable", "worldreadable"}

# Set of keywords indicating OT/operational issues
ot_keywords := {"debug", "shell", "uart", "port", "console", "firmware", "binary", "artifact", "exec", "command", "script"}

# Helper to check if a string matches any pattern in a set
matches_set(str, set) {
    lower_str := lower(str)
    contains(lower_str, set[_])
}

# Traverse and check for public access patterns
check_public_access(node) {
    glitch_lib.traverse(node, "public")
} else {
    glitch_lib.traverse(node, "publicaccess")
} else {
    glitch_lib.traverse(node, "ispublic")
} else {
    glitch_lib.traverse(node, "publiclyaccessible")
} else {
    glitch_lib.traverse(node, "0.0.0.0/0")
} else {
    glitch_lib.traverse(node, "::/0")
} else {
    glitch_lib.traverse(node, "public-read")
}

# Traverse and check for authentication issues
check_auth_issues(node) {
    glitch_lib.traverse(node, "mfa")
} else {
    glitch_lib.traverse(node, "password:")
} else {
    glitch_lib.traverse(node, "root")
} else {
    glitch_lib.traverse(node, "admin")
}

# Traverse and check for IAM over-permission
check_iam_overpermission(node) {
    glitch_lib.traverse(node, "action: *")
} else {
    glitch_lib.traverse(node, "resource: *")
} else {
    glitch_lib.traverse(node, "administratoraccess")
}

# Traverse and check for network boundary issues
check_network_boundary(node) {
    glitch_lib.traverse(node, "publicsubnet")
} else {
    glitch_lib.traverse(node, "internetgateway")
} else {
    glitch_lib.traverse(node, "0.0.0.0/0")
}

# Traverse and check for file permission issues
check_file_permissions(node) {
    glitch_lib.traverse(node, "0777")
} else {
    glitch_lib.traverse(node, "666")
} else {
    glitch_lib.traverse(node, "worldwritable")
}

# Traverse and check for OT issues
check_ot_issues(node) {
    glitch_lib.traverse(node, "debug")
} else {
    glitch_lib.traverse(node, "shell")
} else {
    glitch_lib.traverse(node, "anonymous")
}

# Main rule for public access detection
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

